WITH deduped AS (SELECT * FROM order_items QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity DESC, id ASC) = 1) SELECT product_id, CASE WHEN quantity >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, CORR(unit_price, quantity) AS corr_unit_price_quantity, CORR(quantity, unit_price) AS corr_quantity_unit_price, APPROX_PERCENTILE(quantity, 0.9) AS quantity_p90, APPROX_PERCENTILE(unit_price, 0.95) AS unit_price_p95, COUNT(DISTINCT product_id) AS distinct_product_ids FROM deduped GROUP BY product_id, quantity_tier
